import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/**
 * Cells a feature adds to each person's row in the people table, after the person's own cells.
 * A contribution renders <td> elements; it pairs with a header cell in PersonHead.
 */
export const PersonRow = defineSlot<{ sheetId: string; person: Person }>('person.row');

/** Header cells of the people table, one per PersonRow cell, in the same order. */
export const PersonHead = defineSlot<{ sheetId: string }>('person.head');
features/hold/hold.slot.tsx:60:  PersonHead.fill({ order: 50, Component: HoldHead }),
features/hold/hold.slot.tsx:61:  PersonRow.fill({ order: 50, Component: PersonHold }),
features/claims/claims.slot.tsx:209:  PersonHead.fill({ order: 10, Component: ClaimsHead }),
features/claims/claims.slot.tsx:210:  PersonRow.fill({ order: 10, Component: PersonClaims }),
features/retire/retire.slot.tsx:75:  PersonHead.fill({ order: 40, Component: RetireHead }),
features/retire/retire.slot.tsx:76:  PersonRow.fill({ order: 40, Component: PersonRetire }),
features/rates/rates.slot.tsx:186:  PersonHead.fill({ order: 20, Component: DueHead }),
features/rates/rates.slot.tsx:187:  PersonRow.fill({ order: 20, Component: PersonDueTotal }),
features/statements/statement.slot.tsx:69:  PersonHead.fill({ order: 30, Component: StatementHead }),
features/statements/statement.slot.tsx:70:  PersonRow.fill({ order: 30, Component: PersonStatement }),
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

// `version` is raised by each save; an edit sends the version it was made from. `statementCount`
// is how many statements have been taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and date ('' before the first). `retired` is set once they have a retirement
// date, `retiredFrom` ('' when not retired), whatever that date is. `held` is whether they are on hold: their OPEN claims then count in no total.
export type Person = {
  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
};

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: async () =>
    (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
});

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery(peopleQuery(sheetId));
}

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet keeps it. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

